mapper.select:
SELECT a.aply_id, a.aply_dt, a.aply_stat_cd, p.prg_id, p.prg_nm, s.std_id, s.std_no, s.std_nm, s.sch_yr FROM public.ncs_prg_aply a JOIN public.std_info s ON a.std_id = s.std_id JOIN public.ncs_prg_info p ON a.prg_id = p.prg_id
ORDER BY a.aply_dt DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE public.ncs_prg_aply
SET aply_stat_cd = #{status}
WHERE aply_id = #{aplyId}
